class NomConceptoPDTarifa extends BaseNomConceptoPDTarifa {

    /**
     * Obtener un listado de los datos de las tarifas de concepto dado un identificador de concepto.
     * 
     * @param int $idconceptopd  Identificador del concepto de percepción o descuento.
     * @return array Listado de los datos de las tarifas de concepto.
     */
    public static function obtenerListadoTarifaConcepto($idconceptopd) {

        //Devolviendo el listado de tarifas de conceptos en forma de arreglo.
        return Doctrine_Query::create()
				->select('ct.idconceptopdtarifa, ct.idtarifa, t.denominacion  as denomtarifa , ct.importe, 
						ct.idformula, ct.idformacalculo, ct.lugaresdecimales, fc.denominacion as denomformacalculo')
                ->from('NomConceptoPDTarifa ct')
				->leftjoin('ct.NomTarifa t')
				->leftjoin('ct.NomFormaCalculo fc')
                ->where('idconceptopercepciondescuento = ?', array($idconceptopd))
                ->fetchArray();
    }

    /**
     * Obtener la tarifa de concepto dado el identificador.
     * 
     * @param $idconceptopdtarifa        Identificador de la tarifa de concepto.
     * @return NomConceptoPDTarifa    	 Objeto tarifa de concepto (clase del dominio).
     */
    public static function obtenerObjTarifaConceptoDadoId($idconceptopdtarifa) {
        return Doctrine::getTable('NomConceptoPDTarifa')->find($idconceptopdtarifa);
    }
    
    public static function obtenerImporteXIdConceptoTarifa($idtarifa,$idconcepto) {
        return Doctrine_Query::create()->select('p.importe AS importe')
                        ->from('NomConceptoPDTarifa p')
                        ->where('p.idtarifa = ? and p.idconceptopercepciondescuento=?', array($idtarifa,$idconcepto))
                        ->fetchOne()
                        ->importe;
   }
   
   public static function obtenerIdFormaCalcXIdConceptoTarifa($idtarifa,$idconcepto) {
        return Doctrine_Query::create()->select('p.idformacalculo AS idformacalculo')
                        ->from('NomConceptoPDTarifa p')
                        ->where('p.idtarifa = ? and p.idconceptopercepciondescuento=?', array($idtarifa,$idconcepto))
                        ->fetchOne()
                        ->idformacalculo;
   }
   
   public static function obtenerTarifaXConceptoPD($idconceptopd, $idtarifa) {

        //Devolviendo la tarifa de concepto en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomConceptoPDTarifa')
                ->where('idconceptopercepciondescuento = ? and idtarifa = ?', array($idconceptopd, $idtarifa))
                ->fetchArray();
    }
    
    public static function existeIdTarifaxIdConcepto($idconceptopd, $idtarifa) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomConceptoPDTarifa p')
                ->where('idconceptopercepciondescuento = ? and idtarifa = ?', array($idconceptopd, $idtarifa))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
     
     //Funcion que me devuelve la configuracion de tarifas y formas de calculo de los conceptos de percepcion y descuentos
      public function obtenerTarifasFormaCalculoConceptosPD(){
        $sql = "select tpd.* from mod_nomina.nom_conceptopdtarifa tpd
					inner join mod_nomina.nom_conceptopercepciondescuento pd on (pd.idconceptopercepciondescuento = tpd.idconceptopercepciondescuento)
					where pd.fechafin is null or pd.fechafin >= now();";

		$mg = Doctrine_Manager::getInstance();
		$conn = $mg->getCurrentConnection();
		return $conn->fetchAll($sql);
    }
    
    public static function obtenerTarifaXConceptoPDObj($idconceptopd, $idtarifa) {
        //Devolviendo la tarifa de concepto en forma de objeto.
        return Doctrine_Query::create()
                ->from('NomConceptoPDTarifa')
                ->where('idconceptopercepciondescuento = ? and idtarifa = ?', array($idconceptopd, $idtarifa))
                ->execute();
    }
   

}
